                      "chatgpt": "chatgpt",
                      "claude": "claude",
                      "perplexity": "perplexity",
                      "gemini": "gemini",
                      "grok": "grok",
                      "ai_overviews": "ai_overviews",
                      "ai_mode": "ai_mode"
                    },
                    "options": [
